public class Main {
    static abstract class 小猫 {
        abstract String 叫声();
    }

    static class 橘猫 extends 小猫 {
        @Override
        String 叫声() {
            return "喵～";
        }
    }

    static class 狸花猫 extends 小猫 {
        @Override
        String 叫声() {
            return "喵嗷";
        }
    }

    static 小猫 领养一只(String 花色) {
        if (花色.equals("狸花")) {
            return new 狸花猫();
        }
        if (花色.equals("橘")) {
            return new 橘猫();
        }
        return new 橘猫();
    }

    public static void main(String[] args) {
        for (String 花色 : new String[]{"花", "橘", "狸花"}) {
            System.out.println(花色 + " -> " + 领养一只(花色).叫声());
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public class Main {
    interface 听众 {
        void 听见了(String 菜名);
    }

    static class 开饭铃 {
        List<听众> 名单 = new ArrayList<>();

        void 订上(听众 一位) {
            名单.add(一位);
        }

        void 摇铃(String 菜名) {
            for (听众 一位 : 名单) {
                一位.听见了(菜名);
            }
        }
    }

    static class 猫 implements 听众 {
        String 名字;

        猫(String 名字) {
            this.名字 = 名字;
        }

        public void 听见了(String 菜名) {
            System.out.println(名字 + " 冲向 " + 菜名);
        }
    }

    static class 懒猫 implements 听众 {
        String 名字;

        懒猫(String 名字) {
            this.名字 = 名字;
        }

        public void 听见了(String 菜名) {
            System.out.println(名字 + " 翻了个身，继续睡");
        }
    }

    static class 账房猫 implements 听众 {
        String 名字;

        账房猫(String 名字) {
            this.名字 = 名字;
        }

        public void 听见了(String 菜名) {
            System.out.println(名字 + " 把" + 菜名 + "记了一笔");
        }
    }

    public static void main(String[] args) {
        开饭铃 铃 = new 开饭铃();
        铃.订上(new 猫("小橘"));
        铃.订上(new 懒猫("煤球"));
        铃.订上(new 账房猫("账房"));
        铃.摇铃("小鱼干");
    }
}
